import json,os
def split(grid):
    # find full frontier row or column of a single color; return two regions
    h,w=len(grid),len(grid[0])
    for i in range(h):
        if len(set(grid[i]))==1:
            return grid[:i],grid[i+1:]
    for j in range(w):
        if len({r[j] for r in grid})==1:
            return [r[:j] for r in grid],[r[j+1:] for r in grid]
def transform(grid):
    a,b=split(grid)
    ca={v for r in a for v in r}; cb={v for r in b for v in r}
    shared=(ca&cb).pop()
    ncol=len({v for r in grid for v in r})-1
    return [[ncol if x==y else shared for x,y in zip(ra,rb)] for ra,rb in zip(a,b)]
